// 高吞吐生产者完整配置参考
Properties props = new Properties();
props.put("bootstrap.servers", "broker1:9092,broker2:9092,broker3:9092");

// 批量聚合
props.put("batch.size", String.valueOf(64 * 1024));          // 64KB
props.put("linger.ms", "20");                               // 等待 20ms 聚合

// 压缩
props.put("compression.type", "lz4");                       // 速度最快

// 缓冲
props.put("buffer.memory", String.valueOf(128 * 1024 * 1024)); // 128MB
props.put("max.block.ms", "30000");                         // 缓冲满时最多等 30s

// 可靠性（不牺牲吞吐的情况下保证不丢）
props.put("acks", "all");
props.put("enable.idempotence", "true");
props.put("retries", String.valueOf(Integer.MAX_VALUE));
props.put("delivery.timeout.ms", "120000");

// 单 Poll 线程 + 多处理线程的高吞吐消费模型
ExecutorService executor = Executors.newFixedThreadPool(10);
Map<TopicPartition, Long> completedOffsets = new ConcurrentHashMap<>();

while (running) {
    ConsumerRecords<String, String> records = consumer.poll(Duration.ofMillis(100));

    for (ConsumerRecord<String, String> record : records) {
        TopicPartition tp = new TopicPartition(record.topic(), record.partition());
        long offset = record.offset();
        executor.submit(() -> {
            processRecord(record);  // 异步处理（耗时操作）
            // 记录完成的最大 offset（需要保证同 Partition 内的顺序提交）
            completedOffsets.merge(tp, offset + 1, Math::max);
        });
    }

    // 提交已完成的 offset
    Map<TopicPartition, OffsetAndMetadata> toCommit = new HashMap<>();
    completedOffsets.forEach((tp, off) -> toCommit.put(tp, new OffsetAndMetadata(off)));
    if (!toCommit.isEmpty()) consumer.commitAsync(toCommit, null);
}
